#!/usr/bin/env bash
set -Eeuo pipefail

# Accept only paths and identifiers generated by the GitHub Actions runner.
stage=${1:?Missing the staging directory.}
deployment_id=${2:?Missing the deployment identifier.}
mode=${3:-dry-run}
if [[ "$mode" != 'dry-run' && "$mode" != 'apply' ]]; then
  echo 'Invalid deployment mode.' >&2
  exit 1
fi
if [[ ! "$stage" =~ ^/tmp/manager-main-deploy\.[[:alnum:]]+$ || ! "$deployment_id" =~ ^[a-f0-9]{12}-[0-9]+-[0-9]+$ ]]; then
  echo 'Invalid deployment arguments.' >&2
  exit 1
fi

# Serialize all three repositories while applying code and checking the application.
exec 9>/var/lock/manager-deploy.lock
flock -w 600 9

# Verify PHP syntax with the same PHP version installed in production.
test -f "$stage/public/index.php"
test -f "$stage/.deploy-excludes"
find "$stage/app" "$stage/public" -type f -name '*.php' -print0 \
  | xargs -0 -r -n 1 php -l

# Preserve replaced and deleted files in a backup outside the public web root.
destination=/var/www/izzidoro.com.br/public/manager_main
backup_directory="/var/backups/manager_main/$deployment_id"
# Simulation uses the production filters and delete behavior without changing files.
rsync_options=(
  --archive --no-owner --no-group --omit-dir-times
  --chmod=D755,F644 --delay-updates --delete-delay
  --checksum --itemize-changes --stats
  --exclude-from="$stage/.deploy-excludes"
)
if [[ "$mode" == 'dry-run' ]]; then
  rsync_options+=(--dry-run)
else
  umask 077
  mkdir -p "$backup_directory"
  chmod 700 /var/backups/manager_main "$backup_directory"
  rsync_options+=(--backup --backup-dir="$backup_directory")
fi
rsync "${rsync_options[@]}" "$stage/" "$destination/"

# Check the PHP login entry point instead of the static redirect page.
if [[ "$mode" == 'dry-run' ]]; then
  echo 'Simulation completed; production files were not changed.'
else
  echo "Code deployed. Backup of replaced files: $backup_directory"
fi
if ! curl --fail --silent --show-error --output /dev/null \
  --connect-timeout 10 --max-time 30 \
  --retry 2 --retry-delay 3 \
  --resolve izzidoro.com.br:443:127.0.0.1 \
  'https://izzidoro.com.br/manager_main/public/index.php?url=user/login'; then
  echo "Application health check failed after mode $mode. Check PHP logs and production Config.php." >&2
  exit 1
fi
echo 'Application health check passed.'
